WITH ranked AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY country, city ORDER BY rating DESC NULLS LAST, id) AS rank_in_group FROM suppliers) ranked WHERE rank_in_group = 1) SELECT CASE WHEN rating >= 3.6 THEN 'LARGE' ELSE 'SMALL' END AS rating_tier, city, COUNT(DISTINCT country) AS distinct_countries, COUNT_IF(city = 'Bangkok') AS bangkok_events, MAX(rating) AS max_rating, SORT_ARRAY(COLLECT_SET(country)) AS country_list, COUNT(*) FILTER (WHERE country = 'JP') AS jp_rows FROM ranked GROUP BY CASE WHEN rating >= 3.6 THEN 'LARGE' ELSE 'SMALL' END, city
